questions.modelAnswer:
class Point2D:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def distance_to(self, other):
        return ((self.x - other.x)**2 + (self.y - other.y)**2)**0.5

p = Point2D(0, 0)
q = Point2D(3, 4)
print(p.distance_to(q))   # 5.0

self refers to the point on which the method is called (p), and other is the argument (q).
